describe("services/notification-service", () => {
  // comment.created with mentions produces one comment_mention per mentioned user.
  it("creates one notification per mentioned user", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions issue" }),
    );

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      occurredAt: issue.createdAt,
      commentId: "cmt-mentions-1" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.admin, tenant.userIds.viewer],
    });

    const forAdmin = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });
    const forViewer = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["comment_mention"],
      limit: 25,
      cursor: null,
    });

    expect(forAdmin.items).toHaveLength(1);
    expect(forViewer.items).toHaveLength(1);
    expect(forAdmin.items[0]?.kind).toBe("comment_mention");
  });

  // The actor who caused the event is not notified about their own action.
  it("does not notify the actor about their own action", async () => {
    const rows = await notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.member, tenant.userIds.admin],
      {
        title: "New comment",
        body: "Someone commented",
        href: "/issues/x",
        actorId: tenant.userIds.member,
      },
    );

    expect(rows).toHaveLength(1);
    expect(rows[0]?.recipientId).toBe(tenant.userIds.admin);
  });

  // NotificationPreference.email === false suppresses the email channel only.
  it("honours the per-kind email preference", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "issue_assigned",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], {
      title: "Assigned",
      body: "You were assigned",
      href: "/issues/y",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toEqual(["in_app"]);
  });

  // digestOnly routes the entry to the digest instead of an immediate email.
  it("queues a digestOnly notification for the digest instead of sending", () => {
    const flagsWithDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "growth",
      role: null,
      overrides: undefined,
    };

    const channels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithDigest,
    );

    // The org's plan includes the digest_email flag, so the entry is still
    // routed to the "email" channel — it will go out with the digest run
    // rather than never leaving the in-app row.
    expect(channels).toEqual(["in_app", "email"]);
  });

  // isEnabled("digest_email", …) gates the digest channel by plan.
  it("skips the digest channel when the digest_email flag is off", () => {
    const flagsWithoutDigest: FlagContext = {
      orgId: tenant.org.id,
      userId: null,
      plan: "free",
      role: null,
      overrides: undefined,
    };

    const digestOnlyChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: true,
      },
      flagsWithoutDigest,
    );

    // Without the plan flag, a digestOnly preference loses the email channel
    // entirely (the org has no digest run to defer it to).
    expect(digestOnlyChannels).toEqual(["in_app"]);

    // A non-digestOnly preference is unaffected by the flag.
    const immediateChannels = resolveChannels(
      {
        orgId: tenant.org.id,
        userId: tenant.userIds.admin,
        kind: "digest_ready",
        inApp: true,
        email: true,
        digestOnly: false,
      },
      flagsWithoutDigest,
    );
    expect(immediateChannels).toEqual(["in_app", "email"]);
  });

  // in_app is always recorded, even when email delivery is suppressed.
  it("always records the in-app notification", async () => {
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "member_joined",
      inApp: true,
      email: false,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "member_joined", [tenant.userIds.viewer], {
      title: "Member joined",
      body: "A member joined",
      href: "/settings/members",
      actorId: null,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]?.channels).toContain("in_app");

    const page = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      kind: ["member_joined"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
  });

  // Notifications carry the org id and are only visible inside that tenant.
  it("scopes notifications to the recipient's organization", async () => {
    const other = await createTenant("notify-other", "growth");

    await notify(tenant.org.id, "member_joined", [tenant.userIds.owner], {
      title: "Member joined",
      body: "Welcome",
      href: "/settings/members",
      actorId: null,
    });

    await expect(
      listNotifications(other.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.owner,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const own = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(own.total).toBeGreaterThanOrEqual(1);
  });
});
import "@testing-library/jest-dom/vitest";

import { and, eq, isNull, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, members, organizations, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toMember, toOrganization } from "./_mappers";
import type { OwnershipHandoverRow } from "@/server/db";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Member, Role } from "@/types/member";
import type { Organization, OwnershipHandover, OwnershipHandoverStatus } from "@/types/organization";

function toHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    ...row,
    orgId: row.orgId as OrgId,
    fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId,
    expiresAt: toIsoTimestamp(row.expiresAt),
    createdAt: toIsoTimestamp(row.createdAt),
    resolvedAt: row.resolvedAt === null ? null : toIsoTimestamp(row.resolvedAt),
  };
}

/** All handover reads and writes are synchronous inside a SQLite transaction. */
export function transaction<T>(work: () => T): T {
  return getDb().transaction(work, { behavior: "immediate" });
}

export function findOrganization(orgId: OrgId): Organization | null {
  const row = getDb().select().from(organizations).where(eq(organizations.id, orgId)).get();
  return row ? toOrganization(row) : null;
}

export function findActiveMember(orgId: OrgId, userId: UserId): Member | null {
  const row = getDb().select().from(members).where(and(
    eq(members.orgId, orgId),
    eq(members.userId, userId),
    eq(members.status, "active"),
    isNull(members.archivedAt),
  )).get();
  return row ? toMember(row) : null;
}

/** Includes lapsed rows so the recipient can distinguish expiry from absence. */
export function findUnresolved(orgId: OrgId): OwnershipHandover | null {
  const row = getDb().select().from(ownershipHandovers).where(and(
    eq(ownershipHandovers.orgId, orgId),
    eq(ownershipHandovers.status, "pending"),
  )).get();
  return row ? toHandover(row) : null;
}

export function insert(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: IsoTimestamp,
): OwnershipHandover {
  const expiresAt = toIsoTimestamp(new Date(Date.parse(createdAt) + 7 * 24 * 60 * 60 * 1000));
  const row = getDb().insert(ownershipHandovers).values({
    id: newId(), orgId, fromUserId, toUserId, createdAt, expiresAt,
    status: "pending", resolvedAt: null,
  }).returning().get();
  return toHandover(row);
}

export function resolve(
  handover: OwnershipHandover,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  resolvedAt: IsoTimestamp,
): OwnershipHandover {
  const row = getDb().update(ownershipHandovers).set({ status, resolvedAt }).where(and(
    eq(ownershipHandovers.orgId, handover.orgId),
    eq(ownershipHandovers.id, handover.id),
    eq(ownershipHandovers.status, "pending"),
  )).returning().get();
  if (!row) throw new Error("Ownership handover is no longer pending");
  return toHandover(row);
}

export function setRole(member: Member, role: Role, at: IsoTimestamp): void {
  getDb().update(members).set({ role, updatedAt: at }).where(and(
    eq(members.orgId, member.orgId), eq(members.id, member.id),
  )).run();
}

export function setOwner(orgId: OrgId, ownerId: UserId, at: IsoTimestamp): Organization {
  const row = getDb().update(organizations).set({ ownerId, updatedAt: at })
    .where(eq(organizations.id, orgId)).returning().get();
  return toOrganization(row);
}

/** Called in the same transaction as membership removal. */
export function cancelForMember(orgId: OrgId, userId: UserId, at: IsoTimestamp): void {
  getDb().update(ownershipHandovers).set({ status: "canceled", resolvedAt: at }).where(and(
    eq(ownershipHandovers.orgId, orgId),
    eq(ownershipHandovers.status, "pending"),
    or(eq(ownershipHandovers.fromUserId, userId), eq(ownershipHandovers.toUserId, userId)),
  )).run();
}
/**
 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
 */
import { emit } from "@/lib/event-bus";
import { OwnershipHandoverError } from "@/lib/errors";
import { assertCan } from "@/lib/permissions";
import { assertValidSlug, uniqueSlug } from "@/lib/slug";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as handoverRepo from "@/server/repositories/ownership-handover-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { record } from "./activity-service";
import { actorEnvelope, assertRecordedOwner, envelope, orgResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import { toIsoTimestamp } from "@/types/common";
import type {
  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary, OwnershipHandover } from "@/types/organization";
import type { TaskflowEventMap } from "@/types/event";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const handover = handoverRepo.transaction(() => {
    const org = requireFound(handoverRepo.findOrganization(orgId), "Organization", orgId);
    assertRecordedOwner(actor, org, "org:update");
    requireFound(handoverRepo.findActiveMember(orgId, actor.userId), "Member", actor.userId);
    assertCan({ ...actor, role: "owner" }, "org:update", orgResource(orgId));
    if (toUserId === org.ownerId) throw new OwnershipHandoverError("self");
    requireFound(handoverRepo.findActiveMember(orgId, toUserId), "Member", toUserId);

    const now = toIsoTimestamp(new Date());
    const pending = handoverRepo.findUnresolved(orgId);
    if (pending) {
      if (now < pending.expiresAt) throw new OwnershipHandoverError("pending_exists");
      handoverRepo.resolve(pending, "expired", pending.expiresAt);
    }
    return handoverRepo.insert(orgId, actor.userId, toUserId, now);
  });

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You have been offered workspace ownership",
    body: "Accept the offer to become the workspace owner. This offer expires in seven days.",
    href: "/settings/members",
    actorId: actor.userId,
  });
  return handover;
}

/** A lapsed offer remains untouched when someone tries to act on it. */
function recipientHandover(actor: Actor, orgId: OrgId): OwnershipHandover {
  const handover = handoverRepo.findUnresolved(orgId);
  if (!handover || handover.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (Date.now() >= Date.parse(handover.expiresAt)) {
    throw new OwnershipHandoverError("expired");
  }
  return handover;
}

export async function acceptOwnershipHandover(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const changes: TaskflowEventMap["member.role_changed"][] = [];
  const result = handoverRepo.transaction(() => {
    const handover = recipientHandover(actor, orgId);
    const org = requireFound(handoverRepo.findOrganization(orgId), "Organization", orgId);
    const nextOwner = requireFound(handoverRepo.findActiveMember(orgId, actor.userId), "Member", actor.userId);
    const previousOwner = requireFound(handoverRepo.findActiveMember(orgId, handover.fromUserId), "Member", handover.fromUserId);
    assertRecordedOwner({ ...actor, userId: handover.fromUserId }, org, "org:update");

    const stamp = toIsoTimestamp(new Date());
    // Promote first so even inside the transaction the last owner is retained.
    if (nextOwner.role !== "owner") {
      handoverRepo.setRole(nextOwner, "owner", stamp);
      changes.push({ ...actorEnvelope(actor), memberId: nextOwner.id, from: nextOwner.role, to: "owner" });
    }
    const organization = handoverRepo.setOwner(orgId, actor.userId, stamp);
    if (previousOwner.role === "owner") {
      handoverRepo.setRole(previousOwner, "admin", stamp);
      changes.push({ ...actorEnvelope(actor), memberId: previousOwner.id, from: "owner", to: "admin" });
    }
    handoverRepo.resolve(handover, "accepted", stamp);
    return { organization, handover };
  });

  for (const change of changes) await emit("member.role_changed", change);
  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor), fromUserId: result.handover.fromUserId, toUserId: result.handover.toUserId,
  });
  return result.organization;
}

export async function declineOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  return handoverRepo.transaction(() => {
    const handover = recipientHandover(actor, orgId);
    return handoverRepo.resolve(handover, "declined", toIsoTimestamp(new Date()));
  });
}

export async function cancelOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  return handoverRepo.transaction(() => {
    const org = requireFound(handoverRepo.findOrganization(orgId), "Organization", orgId);
    assertRecordedOwner(actor, org, "org:update");
    assertCan({ ...actor, role: "owner" }, "org:update", orgResource(orgId));
    const handover = handoverRepo.findUnresolved(orgId);
    if (!handover || handover.fromUserId !== actor.userId || Date.now() >= Date.parse(handover.expiresAt)) {
      throw new OwnershipHandoverError("nothing_pending");
    }
    return handoverRepo.resolve(handover, "canceled", toIsoTimestamp(new Date()));
  });
}

export async function getPendingOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  const handover = handoverRepo.findUnresolved(orgId);
  return handover && Date.now() < Date.parse(handover.expiresAt) ? handover : null;
}
/**
 * Membership rows. Every read is filtered by `orgId`; removal is a soft delete.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, count, desc, eq, isNull, like, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { getDb, members, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toMember, toUser } from "./_mappers";
import { cancelForMember } from "./ownership-handover-repository";
import type { ListMembersInput } from "@/schemas/member";
import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Member, MemberWithUser, Role } from "@/types/member";

/**
 * A removed member is archived, never deleted, and no read ever surfaces one:
 * the scope is fixed here rather than threaded through every call site.
 */
const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};

function liveMemberPredicate() {
  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
}

export async function findMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

export async function findMemberById(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .get();
  return row ? toMember(row) : null;
}

/** Cursor-paged member list joined with the user record the UI renders. */
export async function listMembers(
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  const db = getDb();
  const sort = { sortColumn: members.createdAt, idColumn: members.id };

  const filters = compact(
    orgPredicate(members.orgId, input.orgId),
    liveMemberPredicate(),
    input.role === undefined ? undefined : eq(members.role, input.role),
    input.status === undefined ? undefined : eq(members.status, input.status),
    input.query === undefined
      ? undefined
      : or(
          like(users.name, `%${input.query}%`),
          like(users.email, `%${input.query}%`),
        ),
  );

  const total = db
    .select({ value: count() })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters))
    .get();

  const rows = db
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(members.createdAt), desc(members.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
  );
}

/** The seat count every plan check compares against. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

export async function updateMemberRole(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/** Removal is a soft delete so the audit log keeps pointing at a real row. */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  return getDb().transaction(() => {
    const row = getDb()
      .update(members)
      .set({ ...archivePatch(), status: "suspended" })
      .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
      .returning()
      .get();

    if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
    cancelForMember(orgId, row.userId as UserId, toIsoTimestamp(new Date()));
    return toMember(row);
  });
}

export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .run();
}
